-- Allow the versioned fidelity prompt while preserving v1 receipts and exact replay.
-- CREATE OR REPLACE preserves the existing service-only ACL and ownership.
-- No source, policy, payload shape or processing flag changes.
create or replace function public.finish_clinical_recap(p_id uuid,p_result jsonb)returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare j clinical_recap_jobs;a clinical_recap_attempts;m jsonb;p jsonb;c jsonb;hash text;outcome text;lc jsonb;receipt jsonb;begin
 perform public.clinical_recap_lock('policy');select *into j from clinical_recap_jobs where id=(select job_id from clinical_recap_attempts where id=p_id)for update;select *into a from clinical_recap_attempts where id=p_id for update;if not found then perform public.clinical_recap_refuse('not_found');end if;hash:=public.clinical_recap_hash(p_result);
 if a.result_hash is not null then if a.result_hash is distinct from hash then perform public.clinical_recap_refuse('intent_conflict');end if;return jsonb_build_object('job_id',j.id,'attempt_id',a.id,'retained',a.state='completed','outcome',case when a.state='completed'then'completed'else a.error_code end);end if;
 if a.state<>'sending'or a.lease_until<=clock_timestamp()or j.output_id is not null then perform public.clinical_recap_refuse('retry_not_allowed');end if;
 select document into m from clinical_recap_manifests where id=j.manifest_id;c:=public.clinical_recap_current(m);p:=public.clinical_recap_policy_view();
 outcome:=case when not public.clinical_recap_session_ok(j.actor_id,j.session_id)or not public.clinical_recap_session_ok(a.actor_id,a.session_id)then'forbidden'when p->>'status'<>'approved'or(p->>'version')::integer<>j.policy_version then'policy_changed'else'completed'end;
 if outcome<>'completed'then update clinical_recap_attempts set state='failed',result_hash=hash,error_code=outcome,failure_details='{}',finished_at=clock_timestamp()where id=a.id;return jsonb_build_object('job_id',j.id,'attempt_id',a.id,'retained',false,'outcome',outcome);end if;
 -- The source epoch wait can outlast the provider lease; never retain output on an expired dispatch.
 if a.lease_until<=clock_timestamp()then perform public.clinical_recap_refuse('retry_not_allowed');end if;
 perform public.clinical_recap_keys(p_result,array['request_id','response_id','provider_model','contract_version','prompt_version','manifest_sha256','language_context','payload']);if not coalesce(public.clinical_recap_text(p_result->'request_id',200,false),false)or not coalesce(public.clinical_recap_text(p_result->'response_id',200),false)or not coalesce(public.clinical_recap_text(p_result->'provider_model',200,false),false)or p_result->>'contract_version'is distinct from'clinical-recap-v1'or (p_result->>'prompt_version' is null or p_result->>'prompt_version' not in ('lrv-recap-claims-v1','lrv-recap-claims-v2','lrv-recap-claims-v3'))or p_result->>'manifest_sha256'is distinct from j.manifest_sha256 then perform public.clinical_recap_refuse('invalid_request');end if;
 lc:=p_result->'language_context';perform public.clinical_recap_keys(lc,array['version','bundle_sha256','request_sha256']);if jsonb_typeof(lc->'version')is distinct from'string'or lc->>'version'!~'^lrv-vet-en-v[1-9][0-9]{0,3}$'or jsonb_typeof(lc->'bundle_sha256')is distinct from'string'or lc->>'bundle_sha256'!~'^[a-f0-9]{64}$'or jsonb_typeof(lc->'request_sha256')is distinct from'string'or lc->>'request_sha256'!~'^[a-f0-9]{64}$'then perform public.clinical_recap_refuse('invalid_request');end if;
 perform public.clinical_recap_validate_payload(p_result->'payload',m);insert into clinical_recap_outputs(id,job_id,manifest_sha256,payload,payload_sha256,provider_manifest)values(a.id,j.id,j.manifest_sha256,p_result->'payload',public.clinical_recap_hash(p_result->'payload'),p_result-'payload');update clinical_recap_jobs set output_id=a.id where id=j.id;update clinical_recap_attempts set state='completed',result=p_result,result_hash=hash,provider_request_id=p_result->>'request_id',finished_at=clock_timestamp()where id=a.id;return jsonb_build_object('job_id',j.id,'attempt_id',a.id,'retained',true,'outcome','completed');
end $$;
